// TH18 v1.00a Stage 5, MainSub00 (st05.ecl.txt:1030-1051).
// Closure: GirlBlueA01 (S:490-497) -> GirlA01 (S:128-145) -> async GirlA01_at (S:146-186).
// Source local t0 = first MainSub00 iteration.  The phase begins on the control
// enemy's first frame; pattern waits the 120-frame practice buffer, so the first
// source iteration lands at target frame 124 (same shell timing as th18_s5_b2).
const TIME_LIMIT: int = 1500;      // No source timeout; local estimate, see report.md.
const TH18_RICE: int = 480;        // st05.ecl.txt:152 etSprite(0,8,6): type8/color6.

// Source type4 ACCEL appended by S:166/S:328: duration100, direction sentinel
// -9999994 = current bullet angle, scalar 0/0.01/0.02/0.03 by rank.  ACCEL's
// direction is constant, so tangential acceleration is the exact subset.
xformdef BULLET_ACCEL(a: fx) {
    set_accel(a);
    wait(100);            // source ACCEL duration; @N is a post-op wait, so use wait here.
    set_accel(0fx);
}

// S:146-186 GirlA01_at. Per-enemy async: wait60, then source diffI counts
// 3/20/30/40 and inter-shot waits 160/30/20/15.  Every shot reads the player
// angle at its own etOn; the aim mode is 0 (aimed fan) with one way.
async sub girl_shot() {
    wait(60);
    var n: int = 3;
    var gap: int = 160;
    var acc: fx = 0fx;
    var rank: int = global(GVAR_RANK);
    if rank == RANK_NORMAL { n = 20; gap = 30; acc = 0.01fx; }
    if rank == RANK_HARD { n = 30; gap = 20; acc = 0.02fx; }
    if rank == RANK_LUNATIC { n = 40; gap = 15; acc = 0.03fx; }
    for i in 0..n {
        _ = fire(TH18_RICE, 6, $self_x, $self_y, 1.5fx, aim_player(),
                 BULLET_ACCEL(acc), none);
        wait(gap);
    }
}

// S:128-145 GirlA01, entered synchronously from GirlBlueA01.  Source boxes:
// setHurtbox(24,24), setHitbox(16,16); native ordinary circle takes width*0.5.
// Body collision stays active, only shot damage is suppressed for the practice
// shell.  movePosTime(180,4,F0,F1) = QUAD_OUT to the snapshot point.
// S:135-137 then waits 240 and starts the upward VELTIME; mode1 = t^2.
async sub girl(f0: fx, f1: fx) {
    set_invuln(65535);
    set_hurtbox(12fx);
    set_hitbox(8fx);
    spawn girl_shot();
    move_to(180, f0, f1, EASE_QUAD_OUT);
    wait(240);
    move_vel(120, -90deg, 1.2fx, EASE_QUAD_IN);
    loop { wait(1); }
}

// S:1030-1051.  $A=-1; $B=40; each iteration increments A, samples F0, F1, F2
// in that order, creates once, then waits 10.  The "unless (A%8 != 7)" source
// branch sends A%8==7 to +208 and all other indices to -208.
// %RANDF2 is signed [-1,1); %RAND is [0,1).  F0/F1/F2 are creation snapshots.
async sub wave() {
    wait(120);                // practice buffer; no source event is moved into it.
    for i in 0..40 {
        var r0: int = rand(65536) - 32768;
        var r1: int = rand(65536) - 32768;
        var r2: int = rand(65536);
        var f0: fx = ((r0 as fx) / 32768) * 160fx;
        var f1: fx = 64fx + ((r1 as fx) / 32768) * 32fx;
        var y: fx = 256fx + ((r2 as fx) / 65536) * 128fx;
        var x: fx = -208fx;
        if i % 8 == 7 { x = 208fx; }
        _ = spawn_enemy(x, y, 100000, 0, 0, 0, girl(f0, f1));
        wait(10);
    }
    loop { wait(1); }
}

// Practice shell control enemy: fixed at (0,0), no body collision, real wave
// enemies retain their source boxes.  The phase timer starts here; the pattern
// itself holds the 120-frame opening buffer.
async sub wave_main() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, wave, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 100000, 0, 0, 0, wave_main);
    loop { wait(600); }
}
